  'flag.low_discipline.title': 'Wenig Disziplin',
  'flag.low_discipline.body': 'Nur {auto} deiner Wetten nutzen Auto-Cashout. Ohne ihn zu spielen heißt, dem Live-Impuls nachzugeben.',
  'flag.low_discipline.action': 'Setze bei jeder Wette einen Auto-Cashout – er schaltet den Impuls aus.',
  'flag.win_illusion.title': 'Häufig-Gewinn-Illusion',
  'flag.win_illusion.body': 'Du gewinnst {win} der Runden, bist aber netto {net} Gold. Oft zu gewinnen fühlt sich nach Gewinn an – ist es nicht. Kleine Siege verdecken einen großen Verlust.',
  'flag.win_illusion.action': 'Achte aufs Netto, nicht auf die Trefferquote. Kleine Siege verbergen das Bild.',
  'flag.chasing_losses.title': 'Verlusten hinterherjagen',
  'flag.chasing_losses.body': 'Nach einem Verlust erhöhst du deinen Einsatz um etwa {loss}x (vs {win}x nach einem Gewinn). Das ist der Drang, es zurückzuholen – das teuerste Muster.',
  'flag.chasing_losses.action': 'Erhöhe nach einem Verlust NIE den Einsatz; halte ihn gleich oder mach eine Pause.',
  'flag.disciplined.title': 'Diszipliniert',
  'flag.disciplined.body': '{auto} deiner Wetten sind Auto-Cashout und du wirst selten erwischt. Stark – weiter so.',
  'flag.trend_worse.title': 'Trend verschlechtert sich',
  'flag.trend_worse.body': 'In letzter Zeit wirst du öfter erwischt ({recent} vs gesamt {overall}). Vielleicht spielst du überhitzt – mach eine Pause.',
  'flag.trend_better.title': 'Trend verbessert sich',
  'flag.trend_better.body': 'In letzter Zeit wirst du seltener erwischt ({recent} vs {overall}). Deine Disziplin steigt.',
  'av.rounds': '{n} Runden',
  'av.wait': 'Für dein Muster braucht es noch etwas mehr Daten – {have}/{need} Runden. Es wird schärfer, je mehr du spielst.',
  'av.stat.medianCashout': 'Median-Cashout', 'av.stat.caught': 'Erwischt',
  'av.trend.title': 'Erwischt-Trend', 'av.trend.worse': 'Du wirst mit der Zeit öfter erwischt ↑',
  'av.trend.better': 'Du wirst mit der Zeit seltener erwischt ↓', 'av.trend.flat': 'Deine Erwischt-Rate ist stabil →',
  'av.trend.first': 'Anfang', 'av.trend.last': 'Ende', 'av.bar.title': '{rounds} Runden · erwischt {caught}',
  'av.replay.title': 'Der Moment, der dich verrät',
  'av.replay.auto': ', Auto-Cashout bei {target}x', 'av.replay.noauto': ', ohne Auto-Cashout',
  'av.replay.body': 'Du hast {stake} Gold gesetzt{auto}. Das Flugzeug flog bis {crash}x – du hättest jederzeit auszahlen können, bis zu +{missed}. Du hast es nicht getan; alles war weg.',
  'avs.phase.betting': 'Wetten offen', 'avs.phase.flying': 'Fliegt',
  'avs.phase.crashed': 'Weggeflogen – neue Runde bald', 'avs.phase.connecting': 'Verbinde…', 'avs.fair': 'überprüfbar',
  'edge.title': 'Wie die Bank gewinnt',
  'edge.intro': 'Kein Spiel hier ist langfristig zu schlagen – die Quoten begünstigen die Bank. Genau zu wissen wie, ist deine beste Verteidigung.',
  'edge.aviator.h': 'Aviator — die Bank wartet auf Gier',
  'edge.aviator.b': 'Zahlt langfristig etwa 97% zurück (~3% für die Bank). Der Absturzpunkt steht vor der Wette fest und ist überprüfbar. Die Mathematik ist bei jedem Cashout-Ziel neutral – aber nur, wenn du immer auszahlst. Jede Runde, in der das Flugzeug abstürzt, bevor du ziehst, ist ein Totalverlust, und auf größere Multiplikatoren zu warten macht das wahrscheinlicher.',
  'edge.slot.h': 'Gates of Goal — Volatilität ist keine Großzügigkeit',
  'edge.slot.b': 'Zahlt über viele Drehs etwa 96% zurück (~4% für die Bank). Kaskaden und Multiplikatoren wirken großzügig, aber die Gewinntabelle ist so eingestellt, dass langfristig etwa 96 von je 100 gesetztem Gold zurückkommen. Ante und Bonuskauf erhöhen die Schwankungen, nicht deine Rendite.',
  'edge.coupon.h': 'Sportwetten — die Marge erledigt die Arbeit',
  'edge.coupon.b': 'Jeder Markt trägt eine Marge (~3–6%) in der Quote; faire Quoten würden mehr zahlen. Tipps zu kombinieren multipliziert sie: ein 5er-Schein kann über 20% negativen Erwartungswert tragen. Die Bank braucht nie, dass eine einzelne Wette verliert – die Marge zermürbt dich mit der Zeit.',
  'edge.note': 'Deshalb gibt es diesen Spiegel: Der Wert ist nicht, das Spiel zu schlagen, sondern dein eigenes Muster zu verstehen.',
  'rc.title': 'Realitäts-Check',
  'rc.burn_rate': 'In diesem Tempo ist dein Guthaben in etwa {days} Tagen aufgebraucht. Es lohnt sich, langsamer zu machen.',
  'rc.long_session': 'Du spielst heute schon {hours}h ({plays} Runden). Tritt eine Weile zurück.',
  'rc.high_risk': 'Hochrisiko-Zone: diese Woche hast du einen großen Teil deines Guthabens ausradiert. Genau hier lawinen sich Verluste.',
  'lang.label': 'Sprache',
