  'avs.phase.crashed': 'उड़ गया — नया राउंड जल्द', 'avs.phase.connecting': 'कनेक्ट हो रहा…', 'avs.fair': 'सत्यापन-योग्य',
  'edge.title': 'घर कैसे जीतता है',
  'edge.intro': 'यहाँ कोई खेल लंबे समय में नहीं जीता जा सकता — ऑड्स घर के पक्ष में हैं। ठीक-ठीक जानना ही आपका सबसे अच्छा बचाव है।',
  'edge.aviator.h': 'Aviator — घर लालच का इंतज़ार करता है',
  'edge.aviator.b': 'समय के साथ लगभग 97% लौटाता है (~3% घर को)। क्रैश बिंदु दांव से पहले तय और सत्यापन-योग्य होता है। गणित हर कैशआउट लक्ष्य पर तटस्थ है — पर तभी जब आप हमेशा कैश करें। हर राउंड जिसमें विमान आपके कैश करने से पहले क्रैश हो जाए, पूरा नुकसान है, और बड़े गुणकों का इंतज़ार इसे और संभावित बनाता है।',
  'edge.slot.h': 'Gates of Goal — उतार-चढ़ाव उदारता नहीं',
  'edge.slot.b': 'कई स्पिन में लगभग 96% लौटाता है (~4% घर को)। टम्बल और गुणक उदार लगते हैं, पर पेटेबल ऐसे सधा है कि लंबे समय में लगाए हर 100 गोल्ड में से लगभग 96 लौटते हैं। ante और बोनस ख़रीद उतार-चढ़ाव बढ़ाते हैं, आपका रिटर्न नहीं।',
  'edge.coupon.h': 'खेल दांव — काम मार्जिन करता है',
  'edge.coupon.b': 'हर मार्केट के ऑड्स में मार्जिन (~3–6%) बसा होता है; उचित ऑड्स ज़्यादा देते। लेग जोड़ना इसे गुणा करता है: 5-लेग कूपन 20%+ नकारात्मक अपेक्षित मान ला सकता है। घर को किसी एक दांव के हारने की ज़रूरत नहीं — मार्जिन समय के साथ आपको घिसता है।',
